try { m.at(3); } catch (const std::out_of_range& e) {}

// EFFICIENT LOOKUP (Iterator): m.find(key)
if (m.find(1) != m.end()) { /* Use m.find(1)->second */ }

// EFFICIENT EXISTENCE CHECK: m.count(key)
bool exists = (m.count(1) == 1); // 1 or 0 for std::map/set
